**Minimum Length Substring After Deleting Characters with Nearby Matching**

Given two strings `s` and `t`, return the length of the minimum substring that has all characters from `t`. The allowed operations are removing any characters from `s` to obtain the substring, and also removing a character from `s` and its matching character from either the left or the right.

### Code

```python
def min_length_substring(s, t):
    if not s or not t:
        return 0

    t_count = {}
    for char in t:
        t_count[char] = t_count.get(char, 0) + 1

    min_length = float('inf')
    left = 0
    required_chars = len(t_count)
    max_right = {char: i for i, char in enumerate(s)}

    for right in range(len(s)):
        if s[right] in t_count:
            t_count[s[right]] -= 1
            if t_count[s[right]] == 0:
                required_chars -= 1

        while left <= right and required_chars == 0:
            if s[left] in max_right and max_right[s[left]] > right:
                nearby_char = find_nearby(s, left, s[left], max_right)
                if nearby_char is not None:
                    if s[right] in t_count:
                        t_count[s[right]] += 1
                    if s[left] in t_count:
                        t_count[s[left]] -= 1
                    left = nearby_char
                    max_right[s[left]] = max(max_right[s[left]], max_right[right])
                    continue

            min_length = min(min_length, right - left + 1)
            if s[left] in t_count:
                t_count[s[left]] += 1
                required_chars += 1
            left += 1

    return min_length if min_length!= float('inf') else 0

def find_nearby(s, left, char, max_right):
    if left > 0 and s[left-1] == char and max_right[s[left-1]] >= left:
        return left - 1
    if left < len(s) - 1 and s[left+1] == char and max_right[s[left+1]] >= left+1:
        return left + 1
    return None
```

